$:set -euo pipefail
node <<'NODE'
"use strict";
const fs=require("node:fs"), cp=require("node:child_process"), crypto=require("node:crypto");
const dir="workspaces/codespace-mcp-srs-design/local-terminals/templates/";
const file=dir+"agent-return-wrapper.json";
for(const p of ["AGENTS.md","terminals_requirements.json","workspaces/codespace-mcp-srs-design/AGENTS.md","workspaces/codespace-mcp-srs-design/README.md",dir+"agent-command-return.schema.json",file])if(!fs.existsSync(p))throw Error("Missing "+p);
if(!fs.readFileSync("AGENTS.md","utf8").includes("DISCOVERY-04"))throw Error("Wrong repository contract");
const raw=fs.readFileSync(file,"utf8"),x=JSON.parse(raw);
if(x.version!=="1.1.0"||x.derivations.length!==36)throw Error("Unexpected wrapper version or count");
const origin=JSON.parse(fs.readFileSync(dir+"agent-command-return.schema.json","utf8"));
if(x.compatibility.source_schema_id!==origin.$id)throw Error("Wrong source schema");
const algorithms={
 timestamp_difference_ms:"Node.js: Date.parse(end) - Date.parse(start), after validating complete UTC-offset timestamps.",
 map_timestamp_difference_ms:"Node.js: Array.filter(item => start and end exist).map(item => Date.parse(end)-Date.parse(start)); reject negative deltas.",
 present_collection_lengths:"Node.js: Object.hasOwn(source,key) && Array.isArray(source[key]) ? source[key].length : omit.",
 distinct_sorted_values:"Node.js: Array.from(new Set(records.map(item=>item[field]))).sort(numeric_or_lexicographic).",
 project_fields_sorted:"Node.js: records.map(record=>Object.fromEntries(fields.map(k=>[k,record[k]]))).sort(by specified fields); reject duplicate identities.",
 frequency_by_value:"Node.js: records.reduce((counts,item)=> increment counts[item[field]] only when present,{}).",
 count_items_missing_field:"Node.js: records.filter(item => !Object.hasOwn(item,field)).length.",
 map_arithmetic_difference:"Node.js: records.filter(has before and after).map(record=> after_size_bytes-before_size_bytes).",
 sum_numeric_by_group:"Node.js: validate safe integer byte_length; reduce into sum and per-kind/per-stream totals.",
 verify_base64_byte_count_sha256:"Node.js: strict RFC4648 base64 validation; Buffer.from(value,'base64'); compare .length and crypto.createHash('sha256').update(buffer).digest('hex').",
 boolean_frequency:"Node.js: count records whose boolean field is true and false; do not count absent fields.",
 sum_numeric:"Node.js: reduce present, validated numeric sizes; count records where size is absent.",
 group_coverage_records:"Node.js: group source.coverage by category, copying scope/status/method exactly as recorded; no completeness inference.",
 canonical_json_sha256:"Node.js: implement RFC8785/JCS canonicalization followed by crypto.createHash('sha256').update(canonicalUTF8).digest('hex').",
 copy_existing_fields:"Node.js: Object.fromEntries(allowlistedFields.filter(k=>Object.hasOwn(sourceObject,k)).map(k=>[k,sourceObject[k]]))."
};
const keysRequiringUpstreamObservation={
 "DER-001":"source.timestamps.started_at and ended_at, measured by the terminal execution recorder",
 "DER-002":"source.timestamps.received_at and started_at, measured by the terminal execution recorder",
 "DER-003":"source.processes captured from instrumented process launches (not inferred from a post-run process list)",
 "DER-004":"source.jobs populated by GitHub Actions jobs API using recorded run_id and run_attempt",
 "DER-005":"source.steps populated by GitHub Actions jobs API job.steps records",
 "DER-006":"named source arrays populated by recorder/API collector; only present arrays are counted",
 "DER-007":"source.workflows run_id from GitHub Actions run API, linked by observed event/dispatch evidence",
 "DER-008":"source.workflows run_id, run_attempt, repository from GitHub Actions run API",
 "DER-009":"source.jobs job_id from GitHub Actions jobs API",
 "DER-010":"source.artifacts artifact_id from GitHub Actions run artifacts API",
 "DER-011":"source.processes process_record_id assigned by the instrumented runner",
 "DER-012":"source.streams stream_id assigned by pipe/PTY capture",
 "DER-013":"source.files file_record_id from observed filesystem operations or verified Git tree comparisons",
 "DER-014":"source.workflows status returned by GitHub Actions run API",
 "DER-015":"source.workflows conclusion returned by GitHub Actions run API",
 "DER-016":"source.workflows conclusion optional member returned by GitHub Actions run API",
 "DER-017":"source.jobs status returned by GitHub Actions jobs API",
 "DER-018":"source.jobs conclusion returned by GitHub Actions jobs API",
 "DER-019":"source.steps status returned in GitHub Actions job steps",
 "DER-020":"source.steps conclusion returned in GitHub Actions job steps",
 "DER-021":"source.files operation classified by instrumented filesystem event or before/after Git tree comparison",
 "DER-022":"source.files before_size_bytes and after_size_bytes captured or read from verified file versions",
 "DER-023":"source.streams kind and byte_length from byte capture pipes",
 "DER-024":"source.streams data_base64, byte_length and sha256 from byte capture pipes",
 "DER-025":"source.streams complete from capture termination and truncation receipt",
 "DER-026":"source.streams truncated recorded by capture writer",
 "DER-027":"source.stream_chunks byte_length and stream_id from byte capture writer",
 "DER-028":"source.stream_chunks data_base64/byte_length/sha256 from byte capture writer",
 "DER-030":"source.receipts kind from machine-generated command/commit/dispatch/readback receipts",
 "DER-031":"source.faults stage from machine-generated error records",
 "DER-032":"source.artifacts size_in_bytes from GitHub Actions artifacts API",
 "DER-035":"the exact original JSON source supplied as input to the wrapper",
 "DER-036":"source.terminal identity recorded by the terminal launch environment (not inferred from textual output)",
 "DER-037":"source.result and source.termination from child process termination and runner receipt"
};
const remove=new Set(["DER-029","DER-033"]);
const removed=x.derivations.filter(d=>remove.has(d.id));
if(removed.length!==2)throw Error("Expected derivations not found");
x.derivations=x.derivations.filter(d=>!remove.has(d.id));
for(const d of x.derivations){
 const a=algorithms[d.operation],originName=keysRequiringUpstreamObservation[d.id];
 if(!a||!originName)throw Error("No concrete retrieval or calculation recipe for "+d.id+" "+d.operation);
 d.deterministic_population={source:originName,script_algorithm:a,precondition:"Collector supplies the named field with evidence. If unavailable, omit the output; never derive an absent event.",execution:"Only after source schema validation"};
}
x.version="1.2.0";
x.constraints.deterministic_derivations="A derived field is allowed only with an identified programmatically retrievable source and a reproducible script algorithm. Declaring a field in source JSON Schema is not proof that the data exists. If no collector can provide the required value, omit the key; do not guess or substitute a narrative.";
x.constraints.missing_inputs="Unobserved facts are not set to null, zero, false, or empty collections; an output is omitted when its required source cannot be populated by an actual collection mechanism.";
x.constraints.coverage="Unverified completeness declarations and counts of speculative causal relationships are excluded. Record source coverage only, without generating coverage summaries or inferred complete flags.";
x.verification.required_checks=x.verification.required_checks.map(v=>v.replace("All 36 retained derivations","All 34 retained derivations"));
x.verification.required_checks.push("Each retained derivation includes a deterministic_population.source and a deterministic_population.script_algorithm specifying programmatic collection and computation.");
x.verification.required_checks.push("Remove any output whose collector is not actually available at execution time; do not take the existence of source schema members as proof of observability.");
x.change_log=[...(x.change_log||[]),{version:"1.2.0",removed:["DER-029","DER-033"],reason:"Remove unsupported causal/coverage summarization and require an explicit scriptable source and computation for every remaining derived key."}];
const ids=x.derivations.map(d=>d.id);
if(x.derivations.length!==34||new Set(ids).size!==34||x.derivations.some(d=>!d.deterministic_population.script_algorithm))throw Error("Final validation failed");
const content=JSON.stringify(x,null,2)+"\n";
const read=p=>JSON.parse(cp.execFileSync("gh",["api","repos/BestNameYet/Terminals/contents/"+p],{encoding:"utf8"}));
const previous=read(file);
if(Buffer.from(previous.content.replace(/\s/g,""),"base64").toString("utf8")!==raw)throw Error("Remote file does not match baseline");
const payload={branch:"main",sha:previous.sha,message:"docs(local-terminals): require scriptable deterministic return derivations",content:Buffer.from(content).toString("base64")};
const save=JSON.parse(cp.execFileSync("gh",["api","-X","PUT","repos/BestNameYet/Terminals/contents/"+file,"--input","-"],{encoding:"utf8",input:JSON.stringify(payload)}));
const actual=Buffer.from(read(file).content.replace(/\s/g,""),"base64").toString("utf8");
if(actual!==content)throw Error("Remote readback mismatch");
console.log(JSON.stringify({path:file,commit:save.commit.sha,version:x.version,remaining:ids.length,removed:[...remove],verified:true,sha256:crypto.createHash("sha256").update(actual).digest("hex")}));
